private class MessagesPigeonStreamHandler<T>(
    val wrapper: MessagesPigeonEventChannelWrapper<T>
) : EventChannel.StreamHandler {
  var pigeonSink: PigeonEventSink<T>? = null

  override fun onListen(p0: Any?, sink: EventChannel.EventSink) {
    pigeonSink = PigeonEventSink<T>(sink)
    wrapper.onListen(p0, pigeonSink!!)
  }

  override fun onCancel(p0: Any?) {
    pigeonSink = null
    wrapper.onCancel(p0)
  }
}

interface MessagesPigeonEventChannelWrapper<T> {
  open fun onListen(p0: Any?, sink: PigeonEventSink<T>) {}

  open fun onCancel(p0: Any?) {}
}

class PigeonEventSink<T>(private val sink: EventChannel.EventSink) {
  fun success(value: T) {
    sink.success(value)
  }

  fun error(errorCode: String, errorMessage: String?, errorDetails: Any?) {
    sink.error(errorCode, errorMessage, errorDetails)
  }

  fun endOfStream() {
    sink.endOfStream()
  }
}
      
/**
 * Native → Dart: the state machine, fed by the native `Flow` / `AsyncStream`; the native
 * collection ends when the subscription does. One channel per client: the handle `create`
 * returned is the Pigeon `instanceName`. The generated stream must be subscribed once per
 * client (a second `EventChannel` of the same name replaces the first's handler); the Dart
 * client shares one subscription among its listeners.
 */
abstract class SessionStatesStreamHandler : MessagesPigeonEventChannelWrapper<SessionStateMessage> {
  companion object {
    fun register(messenger: BinaryMessenger, streamHandler: SessionStatesStreamHandler, instanceName: String = "") {
      var channelName: String = "dev.flutter.pigeon.versola_oauth.SessionStateEvents.sessionStates"
      if (instanceName.isNotEmpty()) {
        channelName += ".$instanceName"
      }
      val internalStreamHandler = MessagesPigeonStreamHandler<SessionStateMessage>(streamHandler)
      EventChannel(messenger, channelName, MessagesPigeonMethodCodec).setStreamHandler(internalStreamHandler)
    }
  }
// Implement methods from MessagesPigeonEventChannelWrapper
override fun onListen(p0: Any?, sink: PigeonEventSink<SessionStateMessage>) {}

override fun onCancel(p0: Any?) {}
}
      
